pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. (optional) vm.assume(...) / bound(...) to keep params in the ADMISSIBLE domain (keep it WIDE)
        vm.assume(newOwner != address(0));
        // 2. set up the scenario: the current owner must be the caller
        vm.prank(address(this));
        c.transferOwnership(address(this));
        // drive c through transferOwnership as the current owner
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // 3. exactly one assertTrue: owner must equal newOwner
        assertTrue(c.owner() == newOwner);
    }
}

