contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Keep the fuzzed domain wide; only exclude address(0) to prevent trivial current-owner ambiguity.
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(newOwner != address(c));

        // The test contract itself owns the contract (deployer).
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // General rule: after transferOwnership, c.owner() must equal the argument newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

