        vm.assume(newOwner != address(0));
        // transferOwnership as current owner
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // new owner must be able to call an onlyOwner function
        vm.prank(newOwner);
        bool ok = true;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

